int i = 10;
int j = 20;

// Pointer to const int (data is const)
const int* p_c = &i;
// *p_c = 15; // Error: Cannot modify data
p_c = &j;     // OK: Can modify pointer

// Const pointer to int (pointer is const)
int* const c_p = &i;
*c_p = 15;    // OK: Can modify data
// c_p = &j;   // Error: Cannot modify pointer

// Const volatile pointer to const int
const volatile int* const v_c_p = &i;

// Complex declaration parsing:
// Array of 5 const pointers to volatile chars
volatile char* const arr[5];

// Pointer to an array of 3 ints
int (*ptr_to_arr)[3];
